/* The version a frame was read with, for the protocol line */
static const char *
globex_mdp3_version_name(int version)
{
    switch (version) {
    case GLOBEX_MDP3_VERSION_1_13:
        return "1.13";
    case GLOBEX_MDP3_VERSION_1_12:
        return "1.12";
    case GLOBEX_MDP3_VERSION_1_11:
        return "1.11";
    case GLOBEX_MDP3_VERSION_1_10:
        return "1.10";
    case GLOBEX_MDP3_VERSION_1_9:
        return "1.9";
    case GLOBEX_MDP3_VERSION_1_8:
        return "1.8";
    case GLOBEX_MDP3_VERSION_1_6:
        return "1.6";
    case GLOBEX_MDP3_VERSION_1_5:
        return "1.5";
    }

    return "";
}

