/* Select the protocol version, from the preference, the
   schema the frame declares, or the capture clock in seconds
   since the unix epoch */
static int
globex_mdp3_version(uint64_t seconds, int declared)
{
    if (globex_mdp3_pref_version != GLOBEX_MDP3_VERSION_AUTOMATIC) {
        return globex_mdp3_pref_version;
    }

    switch (declared) {
    case 13: return GLOBEX_MDP3_VERSION_1_13;
    case 12: return GLOBEX_MDP3_VERSION_1_12;
    case 11: return GLOBEX_MDP3_VERSION_1_11;
    case 10: return GLOBEX_MDP3_VERSION_1_10;
    case 9: return GLOBEX_MDP3_VERSION_1_9;
    case 8: return GLOBEX_MDP3_VERSION_1_8;
    case 6: return GLOBEX_MDP3_VERSION_1_6;
    case 5: return GLOBEX_MDP3_VERSION_1_5;
    }

    if (seconds >= GLOBEX_MDP3_EFFECTIVE_1_13) {
        return GLOBEX_MDP3_VERSION_1_13;
    }

    if (seconds >= GLOBEX_MDP3_EFFECTIVE_1_12) {
        return GLOBEX_MDP3_VERSION_1_12;
    }

    if (seconds >= GLOBEX_MDP3_EFFECTIVE_1_11) {
        return GLOBEX_MDP3_VERSION_1_11;
    }

    if (seconds >= GLOBEX_MDP3_EFFECTIVE_1_10) {
        return GLOBEX_MDP3_VERSION_1_10;
    }

    if (seconds >= GLOBEX_MDP3_EFFECTIVE_1_9) {
        return GLOBEX_MDP3_VERSION_1_9;
    }

    if (seconds >= GLOBEX_MDP3_EFFECTIVE_1_8) {
        return GLOBEX_MDP3_VERSION_1_8;
    }

    if (seconds >= GLOBEX_MDP3_EFFECTIVE_1_6) {
        return GLOBEX_MDP3_VERSION_1_6;
    }

    return GLOBEX_MDP3_VERSION_1_5;
}

/* What this protocol remembers across the frames of a conversation */
typedef struct globex_mdp3_conversation {
    address initiator;
    uint32_t port;
    bool swapped;
} globex_mdp3_conversation;

/* Record of the frame's conversation, created on its first frame */
static globex_mdp3_conversation *
globex_mdp3_conversation_of(packet_info *pinfo)
{
    conversation_t *conversation = find_or_create_conversation(pinfo);
    globex_mdp3_conversation *state = (globex_mdp3_conversation *)conversation_get_proto_data(conversation, proto_globex_mdp3);

    if (state == NULL) {
        state = wmem_new0(wmem_file_scope(), globex_mdp3_conversation);
        copy_address_wmem(wmem_file_scope(), &state->initiator, &pinfo->src);
        state->port = pinfo->srcport;
        conversation_add_proto_data(conversation, proto_globex_mdp3, state);
    }

    return state;
}

/* Cap the fraction at the preferred decimal places */
static void
globex_mdp3_decimal_places(char *buf)
{
    char *point = strchr(buf, '.');

    if (point == NULL) {
        return;
    }

    unsigned places = globex_mdp3_pref_decimal_places;

    if (places >= strlen(point + 1)) {
        return;
    }

    if (places == 0) {
        *point = '\0';
        return;
    }

    point[1 + places] = '\0';
}

/* Format an implied 4 decimal place value */
static void
globex_mdp3_format_decimal_4_32_nullable(char *buf, uint32_t raw)
{
    int64_t value = (int32_t)raw;

    if (value == 2147483647) {
        snprintf(buf, ITEM_LABEL_LENGTH, "%s", "No Value");
        return;
    }
    int64_t units = value / 10000;
    int64_t fraction = value % 10000;

    if (fraction < 0) {
        fraction = -fraction;
    }

    if (value < 0 && units == 0) {
        snprintf(buf, ITEM_LABEL_LENGTH, "-0.%04" PRId64, fraction);
    }
    else {
        snprintf(buf, ITEM_LABEL_LENGTH, "%" PRId64 ".%04" PRId64, units, fraction);
    }

    globex_mdp3_decimal_places(buf);
}

/* Format an implied 7 decimal place value */
static void
globex_mdp3_format_decimal_7_64(char *buf, uint64_t raw)
{
    int64_t value = (int64_t)raw;
    int64_t units = value / 10000000;
    int64_t fraction = value % 10000000;

    if (fraction < 0) {
        fraction = -fraction;
    }

    if (value < 0 && units == 0) {
        snprintf(buf, ITEM_LABEL_LENGTH, "-0.%07" PRId64, fraction);
    }
    else {
        snprintf(buf, ITEM_LABEL_LENGTH, "%" PRId64 ".%07" PRId64, units, fraction);
    }

    globex_mdp3_decimal_places(buf);
}

