/* Message Header */
static unsigned
dissect_globex_mdp3_message_header(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, unsigned offset)
{
    proto_item *item = NULL;
    proto_tree *group = tree;

    if (globex_mdp3_show_headers) {
        group = proto_tree_add_subtree(tree, tvb, offset, -1, ett_globex_mdp3_message_header, &item, "Message Header");
    }

    unsigned start = offset;

    offset = parse_globex_mdp3_message_size(tvb, pinfo, group, offset);
    offset = dissect_globex_mdp3_simple_binary_header(tvb, pinfo, group, offset);

    proto_item_set_len(item, offset - start);

    return offset;
}

/* Simple Binary Header */
static unsigned
dissect_globex_mdp3_simple_binary_header(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, unsigned offset)
{
    proto_item *item = NULL;
    proto_tree *group = tree;

    if (globex_mdp3_show_headers) {
        group = proto_tree_add_subtree(tree, tvb, offset, -1, ett_globex_mdp3_simple_binary_header, &item, "Simple Binary Header");
    }

    unsigned start = offset;

    offset = parse_globex_mdp3_block_length(tvb, pinfo, group, offset);
    offset = parse_globex_mdp3_template_id(tvb, pinfo, group, offset);
    offset = parse_globex_mdp3_schema_id(tvb, pinfo, group, offset);
    offset = parse_globex_mdp3_version(tvb, pinfo, group, offset);

    proto_item_set_len(item, offset - start);

    return offset;
}

/* Mktdata Message */
static unsigned
dissect_globex_mdp3_mktdata(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, unsigned offset)
{
    unsigned start = offset;


    uint32_t template_id = tvb_get_letohs(tvb, start);

    offset = dissect_globex_mdp3_mktdata_payload(tvb, pinfo, tree, offset, template_id);

    return offset;
}

/* Mdpsessionmgmt Message */
static unsigned
dissect_globex_mdp3_mdpsessionmgmt(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, unsigned offset)
{
    unsigned start = offset;


    uint32_t template_id = tvb_get_letohs(tvb, start);

    offset = dissect_globex_mdp3_mdpsessionmgmt_payload(tvb, pinfo, tree, offset, template_id);

    return offset;
}

/* Channel Reset */
static unsigned
dissect_globex_mdp3_channel_reset(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, unsigned offset)
{
    offset = parse_globex_mdp3_transact_time(tvb, pinfo, tree, offset);
    offset = parse_globex_mdp3_match_event_indicator(tvb, pinfo, tree, offset);
    offset = dissect_globex_mdp3_channel_reset_groups(tvb, pinfo, tree, offset);

    return offset;
}

/* Channel Reset Groups */
static unsigned
dissect_globex_mdp3_channel_reset_groups(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, unsigned offset)
{
    proto_item *item = NULL;
    proto_tree *group = tree;

    if (globex_mdp3_show_structs) {
        group = proto_tree_add_subtree(tree, tvb, offset, -1, ett_globex_mdp3_channel_reset_groups, &item, "Channel Reset Groups");
    }

    unsigned start = offset;

    offset = dissect_globex_mdp3_group_size(tvb, pinfo, group, offset);

    /* Channel Reset Group: Num In Group entries */
    uint32_t num_in_group = tvb_get_uint8(tvb, start + 2);

    for (uint32_t index = 0; index < num_in_group; index++) {
        offset = dissect_globex_mdp3_channel_reset_group(tvb, pinfo, group, offset, index + 1);
    }

    proto_item_set_len(item, offset - start);

    return offset;
}

/* Group Size */
static unsigned
dissect_globex_mdp3_group_size(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, unsigned offset)
{
    proto_item *item = NULL;
    proto_tree *group = tree;

    if (globex_mdp3_show_structs) {
        group = proto_tree_add_subtree(tree, tvb, offset, -1, ett_globex_mdp3_group_size, &item, "Group Size");
    }

    unsigned start = offset;

    offset = parse_globex_mdp3_block_length(tvb, pinfo, group, offset);
    offset = parse_globex_mdp3_num_in_group(tvb, pinfo, group, offset);

    proto_item_set_len(item, offset - start);

    return offset;
}

/* Channel Reset Group */
static unsigned
dissect_globex_mdp3_channel_reset_group(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, unsigned offset, uint32_t index)
{
    proto_item *item = NULL;
    proto_tree *group = tree;

    if (globex_mdp3_show_structs) {
        group = globex_mdp3_pref_show_indexes
            ? proto_tree_add_subtree_format(tree, tvb, offset, -1, ett_globex_mdp3_channel_reset_group, &item, "Channel Reset Group %u", index)
            : proto_tree_add_subtree(tree, tvb, offset, -1, ett_globex_mdp3_channel_reset_group, &item, "Channel Reset Group");
    }

    unsigned start = offset;

    offset = parse_globex_mdp3_appl_id(tvb, pinfo, group, offset);

    proto_item_set_len(item, offset - start);

    return offset;
}

