        group = globex_mdp3_pref_show_indexes
            ? proto_tree_add_subtree_format(tree, tvb, offset, -1, ett_globex_mdp3_repo_underlyings_group_v110, &item, "Repo Underlyings Group %u", index)
            : proto_tree_add_subtree(tree, tvb, offset, -1, ett_globex_mdp3_repo_underlyings_group_v110, &item, "Repo Underlyings Group");
