void
proto_reg_handoff_globex_mdp3(void)
{
    heur_dissector_add("udp", dissect_globex_mdp3_udp_heur, "Cme Mdp3 over UDP",
        "globex_mdp3_udp", proto_globex_mdp3, HEURISTIC_ENABLE);
    heur_dissector_add("tcp", dissect_globex_mdp3_tcp_heur, "Cme Mdp3 over TCP",
        "globex_mdp3_tcp", proto_globex_mdp3, HEURISTIC_ENABLE);

    dissector_add_for_decode_as("udp.port", globex_mdp3_handle);
    dissector_add_for_decode_as("tcp.port", globex_mdp3_handle);
}
